          "recomendacao": "Elaborar e monitorar as avaliações de riscos dos programas de: prevenção de incêndio, materiais perigosos e gerenciamento de emergências e catástrofes. Incluir na avaliação de riscos institucional os riscos do programa de gerenciamento das instalações conforme definido pelo hospital e enviar anualmente ao governo.",
