          "recomendacao": "Assegurar o treinamento sobre mudanças climáticas e seu impacto na saúde, prevenção da violência no local de trabalho e prevenção de incêndio para todos os profissionais clínicos e não clínicos. Garantir que todos os profissionais participem do processo de integração antes de iniciar as suas atividades.",
