          "capitulo": "APR",
          "padrao": "APR.08.00",
          "numero": 2,
          "texto": "O hospital informa sua equipe e corpo médico que não tomará nenhuma medida disciplinar ou punitiva porque um profissional, médico ou outro indivíduo que fornece cuidados, tratamento e serviços relata preocupações de segurança ou qualidade de atendimento à JCI.",
