          "capitulo": "APR",
          "padrao": "APR.08.00",
          "numero": 3,
          "texto": "O hospital não toma nenhuma ação disciplinar ou punitiva contra profissionais, médicos ou outros indivíduos que fornecem cuidados, tratamento e serviços quando relatam preocupações de segurança ou qualidade de atendimento à JCI.",
