          "capitulo": "APR",
          "padrao": "APR.11.00",
          "numero": 1,
          "texto": "O hospital oferece cuidados, tratamento, serviços e um ambiente que não representa risco de uma \"Ameaça Imediata à Saúde ou Segurança\" (“Immediate Threat to Health or Safety”).",
