          "capitulo": "ACC",
          "padrao": "ACC.01.00",
          "numero": 5,
          "texto": "D As avaliações e tratamentos realizados antes da transferência estão documentados em um registo mantido pelo hospital que transfere. (Ver também ACC.03.00, EM 4)",
