          "capitulo": "ACC",
          "padrao": "ACC.04.05",
          "numero": 1,
          "texto": "D Existe um processo escrito para gerenciar pacientes que saem contra orientação médica; esse processo inclui o seguinte: •Pacientes internados que saem informando e sem informar a equipe do hospital •Pacientes que fugiram •Pacientes recebendo tratamento complexo que não completam ou não retornam para tratamento (\"no shows\") •Requisitos de documentação",
