          "capitulo": "ACC",
          "padrao": "ACC.04.05",
          "numero": 5,
          "texto": "O processo é consistente com as leis e regulamentos aplicáveis, incluindo requisitos para relatar casos de doenças infecciosas e quando os pacientes podem ser uma ameaça para si mesmos ou para outros.",
