          "padrao": "ACC.04.05",
          "numero": 6,
          "texto": "Quando consistente com as leis e regulamentos regionais, o hospital desenvolve um processo para permitir que os pacientes deixem o hospital durante o curso planejado do tratamento por um período de tempo definido.",
