          "capitulo": "ACC",
          "padrao": "ACC.05.00",
          "numero": 3,
          "texto": "O processo de transferência identifica quem é responsável por monitorar o paciente durante a transferência e as qualificações da equipe necessárias para o tipo de paciente que está sendo transferido.",
