          "numero": 1,
          "texto": "O hospital inclui as seguintes fontes, no mínimo, ao definir suas populações vulneráveis: •Lista predeterminada de populações generalizadas conforme aplicável ao escopo de serviços do hospital •Determinado pelos resultados da avaliação anual dos riscos •Em acordo com leis e regulamentos",
