          "numero": 2,
          "texto": "D A lista predeterminada do hospital inclui as seguintes populações vulneráveis, conforme aplicável ao escopo de serviços do hospital: •Deficientes e doentes crônicos •Socioeconomicamente desfavorecidos •Idoso/frágil •Crianças/adolescentes •Minorias raciais / étnicas •Minorias Sexuais",
