          "numero": 3,
          "texto": "D O hospital desenvolve uma política escrita que aborda a divulgação de erros clínicos a pacientes que inclui, no mínimo, o seguinte: •Como o hospital define o erro clínico •Circunstâncias em que se recomenda a divulgação de um erro clínico •Quem é responsável por notificar um paciente sobre um erro clínico •Outras pessoas ou entidades que devem ser notificadas, quando aplicável",
