          "texto": "Quando o hospital está localizado dentro de um edifício multiuso, os líderes do hospital obtêm evidências de conformidade com leis, regulamentos, códigos, relatórios de inspeção de instalações, requisitos de manutenção de sistemas utilitários e outros requisitos relacionados a sistemas compartilhados e problemas de construção",
