          "capitulo": "FMS",
          "padrao": "FMS.01.01",
          "numero": 1,
          "texto": "D Supervisão e orientação da estrutura de gerenciamento e segurança da instalação é atribuída a um (s) indivíduo (s) qualificado (s) por experiência e treinamento e a evidência da experiência e treinamento é documentada. (Veja também GLD.06.00, EM 1)",
