          "capitulo": "FMS",
          "padrao": "FMS.01.01",
          "numero": 2,
          "texto": "O(s) indivíduo(s) qualificado(s) é(são) responsável(is) por garantir o seguinte: •Recomendações de espaço, tecnologia e outros recursos para apoiar o gerenciamento de instalações e a estrutura de segurança são fornecidas aos líderes do hospital. •Os programas de gerenciamento e segurança de instalações são atuais e totalmente implementados. •Profissionais e outros são treinados nos programas. •Os programas são coordenados, avaliados e monitorados. •Os programas são revisados e atualizados pelo menos anualmente, ou com mais frequência, se necessário (por exemplo, quando há mudanças nos requisitos das leis e regulamentos do país ou mudanças nas instalações, sistemas ou equipamentos do hospital).",
