          "numero": 2,
          "texto": "D O hospital tem uma inspeção de segurança documentada, atual e precisa de suas instalações físicas. Os resultados da inspeção da instalação são revisados e abordados em uma avaliação de risco abrangente em toda a instalação. (Veja também FMS.02.00, EM 1)",
          "classificacao": "NC",
