          "texto": "D Uma avaliação de risco abrangente do hospital, em toda a instalação, conforme exigido pelo FMS.02.00, EM 1, inclui a avaliação dos seguintes riscos relacionados a incêndio: •Separações de fogo •Separações/compartimentos de fumaça •Áreas perigosas (e espaços acima dos tetos nessas áreas), como salas de roupa suja, salas de coleta de lixo e salas de armazenamento de gás medicinal •Saídas de incêndio •Cozinha e aparelhos de cozinha produtores de gordura •Calhas de lavanderia e lixo •Sistemas e equipamentos de energia de emergência •Componentes do sistema de gás medicinal e vácuo •Armazenamento e manuseio de materiais potencialmente inflamáveis (por exemplo, líquidos inflamáveis, gases combustíveis, gases medicinais oxidantes, como oxigênio e óxido nitroso) •Procedimentos e precauções para prevenir e gerenciar incêndios cirúrgicos •Riscos de incêndio relacionados a projetos de construção, reforma ou demolição",
