          "capitulo": "FMS",
          "padrao": "FMS.07.01",
          "numero": 3,
          "texto": "O programa de gerenciamento de equipamentos médicos aborda o uso de qualquer equipamento médico com um problema ou falha relatada ou que seja objeto de um aviso de perigo ou esteja sob recall.",
