          "capitulo": "FMS",
          "padrao": "FMS.08.00",
          "numero": 1,
          "texto": "D O hospital desenvolve e implementa um programa escrito para o gerenciamento de sistemas utilitários em todo o hospital. (Veja também HCT.01.04, EM 1)",
