          "capitulo": "FMS",
          "padrao": "FMS.08.00",
          "numero": 4,
          "texto": "D O hospital identifica, por escrito, as atividades e intervalos para inspecionar, avaliar e realizar manutenção preventiva e de rotina em todos os componentes operacionais dos sistemas utilitários no inventário, com base em critérios como recomendações dos fabricantes, níveis de risco e experiência do hospital.",
