          "capitulo": "FMS",
          "padrao": "FMS.08.01",
          "numero": 2,
          "texto": "D O hospital testa e avalia a disponibilidade e a qualidade da(s) fonte(s) alternativa(s) de água pelo menos anualmente ou com mais frequência, se exigido pelas leis e regulamentos locais ou condições da fonte de água. O hospital documenta os resultados dos testes.",
          "classificacao": "NC",
