          "padrao": "FMS.08.01",
          "numero": 3,
          "texto": "D O hospital testa e avalia fontes alternativas de energia pelo menos trimestralmente ou com mais frequência se exigido pelas leis e regulamentos locais, recomendações dos fabricantes ou condições da fonte de energia. O hospital documenta os resultados dos testes.",
