          "capitulo": "FMS",
          "padrao": "FMS.08.02",
          "numero": 2,
          "texto": "D A qualidade da água não potável é testada e avaliada pelo menos a cada seis (6) meses ou mais frequentemente com base em leis e regulamentos locais, condições das fontes de água e experiência anterior com problemas de qualidade da água. Os resultados do teste são documentados.",
