          "capitulo": "FMS",
          "padrao": "FMS.08.03",
          "numero": 1,
          "texto": "Serviços de hemodiálise no hospital, seguem os padrões da indústria e as diretrizes profissionais para manter a qualidade da água e implementar medidas de prevenção e controle de infecções.",
