          "numero": 2,
          "texto": "2.D A água usada na hemodiálise é testada de acordo com as diretrizes baseadas em evidências antes e durante os tratamentos e avaliados mensalmente quanto ao crescimento bacteriano e endotoxinas e avaliados anualmente quanto a contaminantes químicos. Os resultados do teste são documentados.",
