          "numero": 3,
          "texto": "O hospital opera e mantém o fluxo de ar, sistemas de ventilação e controles de umidade de maneira a minimizar o risco de infecção no hospital, de acordo com as leis e regulamentos locais e nacionais e diretrizes profissionais.",
