          "numero": 1,
          "texto": "D Ao planejar para projetos de construção, reforma ou demolição, ou atividades de manutenção que afetam o atendimento ao paciente, o hospital realiza uma avaliação de risco pré- construção (PCRA) que inclui, no mínimo, o seguinte: •Qualidade do ar •Prevenção e controle de infecções •Sistemas Utilitários •Ruído •Vibração •Materiais e resíduos perigosos •Segurança contra incêndios •Proteção •Procedimentos de emergência, incluindo vias/saídas alternativas e acesso a serviços de emergência •Outros perigos que afetam o cuidado, o tratamento e os serviços (ver também FMS.02.00, EM 1)",
