          "numero": 2,
          "texto": "O(s) diretor(s) geral(s) recomenda(m) políticas, planos estratégicos e orçamentos à entidade de governo.",
          "classificacao": "NC",
          "achado": "Em análise de documentos foi identificado que o hospital ainda não elaborou todos os documentos exigidos pelo Manual da JCI 8ª edição como por exemplo: documentos do capitulo GHI, política para gestão de erros clínicos, programa de prevenção da violência no local de trabalho, diretrizes para avaliação da prática profissional focada, procedimento definindo o processo de avaliação e reavaliação de pacientes, procedimento identificando pacientes e populações especiais que requerem modificação no processo de avaliação, política/procedimento definindo o processo de concessão de privilégios clínicos temporários, política para fornecer atendimento uniforme aos pacientes, a partir do pronto atendimento, garantindo o acesso, a continuidade, os recursos alocados e o escopo dos tratamentos e serviços fornecidos para o cuidado do paciente de forma comparável em todo o hospital, entre outros.",
