          "numero": 2,
          "texto": "Os líderes do hospital são responsáveis por criar as políticas e procedimentos necessários para realizar a missão.",
          "classificacao": "NC",
          "achado": "Em análise de documentos foi observado que os líderes ainda não criaram todas as políticas e procedimentos necessários para realizar a missão, tais como: documentos do capitulo GHI, política para gestão de erros clínicos, programa de prevenção da violência no local de trabalho, diretrizes para avaliação da prática profissional focada, procedimento definindo o processo de avaliação e reavaliação de pacientes, procedimento identificando pacientes e populações especiais que requerem modificação no processo de avaliação, política/procedimento definindo o processo de concessão de privilégios clínicos temporários, política para fornecer atendimento uniforme aos pacientes, a partir do pronto atendimento, garantindo o acesso, a continuidade, os recursos alocados e o escopo dos tratamentos e serviços fornecidos para o cuidado do paciente de forma comparável em todo o hospital, entre outros.",
