          "padrao": "GLD.03.00",
          "numero": 3,
          "texto": "Os líderes do hospital garantem que as políticas e procedimentos sejam seguidos.",
          "classificacao": "NC",
          "achado": "Em análise de documentos e entrevistas com os profissionais foi identificado que os requisitos da norma zero não estão sendo seguidos, foram observados documentos vencidos e layout não padronizado. O registro das informações do paciente nos sumários de transferência e alta, não estão sendo realizados conforme protocolo institucional, contendo siglas e abreviaturas; o Plano de Atendimento a Desastres e Catástrofes e o Programa de Preparo para Emergências de Doenças Transmissíveis Globais não foram testados.",
