          "padrao": "GLD.03.01",
          "numero": 1,
          "texto": "Os líderes do hospital determinam e planejam com os líderes de departamento/serviço o tipo de atendimento, tratamento e serviços a serem prestados pelo hospital que sejam consistentes com a missão do hospital e as necessidades do pacientes atendidos. (Veja também SQE.01.05, EM 1)",
