          "numero": 2,
          "texto": "Os líderes do hospital se comunicam com as principais partes interessadas na comunidade do hospital para facilitar o acesso aos cuidados e o acesso às informações sobre seus serviços de atendimento ao paciente. (Veja também MOI.01.00, EM 1)",
