          "capitulo": "GLD",
          "padrao": "GLD.03.01",
          "numero": 3,
          "texto": "Os líderes do hospital fornecem dados e comunicam informações relacionadas à segurança e qualidade dos serviços do hospital às partes interessadas, que incluem equipe de enfermagem, equipe não clínica e administrativa, pacientes, familiares e partes interessadas externas.",
