          "capitulo": "GLD",
          "padrao": "GLD.04.00",
          "numero": 3,
          "texto": "Os líderes do hospital determinam como o programa será dirigido e gerenciado diariamente e garantem que o programa tenha recursos adequados para ser eficaz. (Veja também QPS.01.00, EM 1)",
          "classificacao": "C",
          "achado": "Nenhum comentário.",
