          "padrao": "GLD.04.00",
          "numero": 4,
          "texto": "Os líderes hospital implementam uma estrutura e um processo para o monitoramento e coordenação geral do programa de qualidade e segurança do paciente. (Veja também PCI.08.00, EM 3)",
