          "numero": 5,
          "texto": "D Os líderes do hospital definem, por escrito, eventos de segurança do doente, incluindo eventos sentinela, conforme descrito no capítulo \"Política de Eventos Sentinela\" (SE) deste manual e incentivam relatórios externos voluntários de programas como o Banco de Dados de Eventos Sentinela da Joint Commission International, além de programas obrigatórios de acordo com as leis e regulamentos, quando aplicável.",
