          "numero": 6,
          "texto": "O hospital realiza análises sistemáticas abrangentes, completas e confiáveis (por exemplo, análises de causa raiz) em resposta a eventos sentinela, conforme descrito no capítulo \"Política de Eventos Sentinela\" (SE) deste manual.",
