          "padrao": "GLD.04.00",
          "numero": 7,
          "texto": "Os líderes do hospital estabelecem um processo para fornecer ativamente sistemas de apoio para a equipe que está envolvida em um evento adverso ou em um evento sentinela. (Veja também FMS.07.01, EM 2)",
