          "capitulo": "HCT",
          "padrao": "HCT.01.00",
          "numero": 2,
          "texto": "Os líderes do hospital identificam um indivíduo qualificado para supervisionar sistemas e processos tecnológicos. (Veja também GLD.06.00, EM 1)",
