          "padrao": "MOI.02.00",
          "numero": 4,
          "texto": "Os requisitos do documento de orientação são implementados e evidentes nas políticas, procedimentos e programas encontrados em todo o hospital.",
          "classificacao": "NC",
          "achado": "Foram apresentados planos com datas de validades de 2 anos como por exemplo: Plano de Emergência Contra Incêndio e Abandono elaborado em 23/10/26 com validade 23/10/28, o PMI298 - Elaborado em 02/04/2026 com validade de 02/04/2028. Foram apresentados documentos vencidos e layout não padronizado. O registro das informações do paciente nos sumários de transferência e alta, não estão sendo realizados conforme protocolo institucional, o Plano de Atendimento a Desastres e Catástrofes e o Programa de Preparo para Emergências de Doenças Transmissíveis Globais não foram testados.",
