          "padrao": "MOI.02.01",
          "numero": 1,
          "texto": "As políticas, procedimentos e planos necessários estão disponíveis e a equipe entende como acessar os documentos relevantes para suas responsabilidades.",
          "classificacao": "NC",
          "achado": "Não foram apresentados os documentos exigidos pelo manual a saber: documentos do capitulo GHI, política para gestão de erros clínicos, programa de prevenção da violência no local de trabalho, diretrizes para avaliação da prática profissional focada, procedimento definindo o processo de avaliação e reavaliação de pacientes, procedimento identificando pacientes e populações especiais que requerem modificação no processo de avaliação, política/procedimento definindo o processo de concessão de privilégios clínicos temporários, politica para fornecer atendimento uniforme aos pacientes, a partir do pronto atendimento, garantindo o acesso, a continuidade, os recursos alocados e o escopo dos tratamentos e serviços fornecidos para o cuidado do paciente de forma comparável em todo o hospital, entre outros.",
