          "capitulo": "MOI",
          "padrao": "MOI.03.00",
          "numero": 1,
          "texto": "O prontuário do paciente contém o seguinte: •Pelo menos dois identificadores únicos para cada artigo (ver também IPSG.01.00, EM 1) •Autor de cada registro •Data de cada registro •Hora de cada registro",
