          "capitulo": "PCI",
          "padrao": "PCI.01.00",
          "numero": 3,
          "texto": "Esse indivíduo(s) coordena com os líderes do hospital as prioridades, recursos e oportunidades de melhoria da qualidade relacionadas ao programa de prevenção e controle de infecções.",
