          "padrao": "PCI.06.00",
          "numero": 1,
          "texto": "D O hospital armazena alimentos e nutrição de maneira a reduzir o risco de infecção, incluindo aqueles armazenados fora da cozinha e das áreas de preparação de alimentos.",
