          "capitulo": "QPS",
          "padrao": "QPS.03.00",
          "numero": 2,
          "texto": "Dados e informações agregados apoiam o atendimento, o tratamento e os serviços do paciente; a gestão hospitalar; a revisão da prática profissional; e o programa geral de qualidade e segurança do paciente. (Ver também PCC.02.02, EM 2; QPS.03.02, EM 1)",
