          "padrao": "QPS.03.03",
          "numero": 2,
          "texto": "A equipe do programa de qualidade e segurança do paciente trabalha com outras unidades, como recursos humanos, tecnologia da informação e finanças, para decidir quais dados devem ser coletados.",
