          "capitulo": "QPS",
          "padrao": "QPS.03.04",
          "numero": 2,
          "texto": "D O hospital conduz uma análise intensiva, ou uma análise sistemática abrangente, de dados quando ocorrem eventos adversos, padrões ou tendências indesejáveis.",
