          "padrao": "QPS.04.01",
          "numero": 2,
          "texto": "Líderes do hospital identificam e priorizam os riscos potenciais que podem ter o maior impacto sobre segurança do paciente e da equipe e na qualidade do atendimento, tratamento e serviços do paciente.",
