          "padrao": "SQE.01.00",
          "numero": 1,
          "texto": "D Os líderes de departamento e/ou de serviço consideram os seguintes elementos para projetar as necessidades dos membros da equipe: •Missão do hospital •Composição de populações de pacientes atendidas pelo hospital e a complexidade as necessidades de atendimento ao paciente •Escopo dos serviços prestados pelo hospital •Volume de pacientes •Equipamento médico e tecnologia utilizados no atendimento ao paciente (Ver também GLD.06.00, EM 2)",
