          "capitulo": "SQE",
          "padrao": "SQE.01.07",
          "numero": 1,
          "texto": "Os membros da equipe participam de educação e treinamento continuados para manter ou aumentar sua competência e conforme necessário. (Veja também AOP.05.02, EM 2)",
