          "capitulo": "SQE",
          "padrao": "SQE.03.00",
          "numero": 2,
          "texto": "D Educação, treinamento e as certificações são verificadas a partir da fonte original de acordo com os parâmetros encontrados no propósito de SQE.05.01 e são documentadas.",
          "classificacao": "C",
          "achado": "Nenhum comentário.",
