          "padrao": "SQE.05.01",
          "numero": 3,
          "texto": "Quando uma terceira parte de verificação é usada, hospital verifica se o terceiro (por exemplo, uma agência governamental) implementa o processo de verificação conforme descrito na política e/ou nas leis e regulamentos e se o processo atende às seguintes expectativas:. •O hospital afiliado que já realizou a verificação de fonte primária do candidato ao corpo médico é aceitável se o hospital afiliado tiver a acreditação atual da Joint Commission International (JCI) com \"total conformidade\" em seu processo de verificação encontrado em SQE.05.01, EMs 1 e 2. •O hospital que baseia suas decisões em parte em informações de uma agência designada, oficial, governamental ou não governamental, deve avaliar a agência que fornece as informações inicialmente e depois periodicamente para garantir que os padrões da JCI continuem a ser atendidos.",
